package agents

import (
	"context"
	"os"
	"strconv"
	"strings"
	"time"
)

// Output holds the result of running an agent prompt.
type Output struct {
	Command  string
	Stdout   string
	Stderr   string
	ExitCode int
}

// Option configures how an agent prompt is executed.
type Option func(*runConfig)
type runConfig struct {
	Model          string
	PermissionMode string
	PromptTimeout  time.Duration
}

// WithModel sets the model to use for the prompt.
func WithModel(model string) Option {
	return func(c *runConfig) { c.Model = model }
}

// WithPermissionMode sets the permission mode for the prompt.
func WithPermissionMode(mode string) Option {
	return func(c *runConfig) { c.PermissionMode = mode }
}

// WithPromptTimeout sets a custom timeout for the prompt execution.
func WithPromptTimeout(d time.Duration) Option {
	return func(c *runConfig) { c.PromptTimeout = d }
}

// Agent defines the interface for an AI coding agent that can be tested.
type Agent interface {
	Name() string
	// Binary returns the CLI binary name (e.g. "kiro-cli-chat").
	Binary() string
	EntireAgent() string
	PromptPattern() string
	// TimeoutMultiplier returns a factor applied to per-test timeouts.
	// Slower agents return values > 1.
	TimeoutMultiplier() float64
	RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error)
	StartSession(ctx context.Context, dir string) (Session, error)
	// Bootstrap performs one-time CI setup (auth config, warmup, etc.).
	// Called before any tests run. Implementations should be idempotent.
	Bootstrap() error
	// IsTransientError returns true if the error from RunPrompt looks like
	// a transient API failure (e.g. 500, rate limit, network error) that
	// is worth retrying.
	IsTransientError(out Output, err error) bool
}

// Session represents an interactive terminal session with an agent.
type Session interface {
	Send(input string) error
	WaitFor(pattern string, timeout time.Duration) (string, error)
	Capture() string
	Close() error
}

// ExternalAgent is an optional interface for agents discovered via the
// external agent protocol (entire-agent-* binaries). SetupRepo uses this
// to pre-configure external_agents in settings before running `entire enable`.
type ExternalAgent interface {
	IsExternalAgent() bool
}

var registry []Agent
var gates = map[string]chan struct{}{}

// Register adds an agent to the global registry.
func Register(a Agent) {
	registry = append(registry, a)
}

// RegisterGate sets a concurrency limit for an agent's tests.
// Tests call AcquireSlot/ReleaseSlot to respect this limit.
// The limit can be overridden via E2E_CONCURRENT_TEST_LIMIT.
func RegisterGate(name string, defaultMax int) {
	max := defaultMax
	if v, err := strconv.Atoi(os.Getenv("E2E_CONCURRENT_TEST_LIMIT")); err == nil && v > 0 {
		max = v
	}
	gates[name] = make(chan struct{}, max)
}

// AcquireSlot blocks until a test slot is available for the agent or the
// context is cancelled. Returns a non-nil error if the context expires
// before a slot opens.
func AcquireSlot(ctx context.Context, a Agent) error {
	g, ok := gates[a.Name()]
	if !ok {
		return nil
	}
	select {
	case g <- struct{}{}:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

// ReleaseSlot frees a test slot for the agent.
func ReleaseSlot(a Agent) {
	if g, ok := gates[a.Name()]; ok {
		<-g
	}
}

// All returns all registered agents.
func All() []Agent {
	return registry
}

// filterEnv returns env with entries matching any of the given variable names
// removed. Used to strip test-only overrides from agent processes.
func filterEnv(env []string, names ...string) []string {
	out := make([]string, 0, len(env))
	for _, e := range env {
		skip := false
		for _, name := range names {
			if strings.HasPrefix(e, name+"=") {
				skip = true
				break
			}
		}
		if !skip {
			out = append(out, e)
		}
	}
	return out
}

package agents

import (
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"strings"
	"time"
)

// TmuxSession implements Session using tmux for PTY-based interactive agents.
type TmuxSession struct {
	name         string
	stableAtSend string   // stable content snapshot when Send was last called
	cleanups     []func() // run on Close
}

// OnClose registers a function to run when the session is closed.
func (s *TmuxSession) OnClose(fn func()) {
	s.cleanups = append(s.cleanups, fn)
}

// NewTmuxSession creates a new tmux session running the given command in dir.
// unsetEnv lists environment variable names to strip from the session.
//
// The command is wrapped with `env` to propagate PATH from the current process.
// tmux sessions inherit the tmux server's environment (not the client's), so
// without this, binaries added to PATH by the test runner would not be found.
func NewTmuxSession(name string, dir string, unsetEnv []string, command string, args ...string) (*TmuxSession, error) {
	s := &TmuxSession{name: name}

	tmuxArgs := []string{"new-session", "-d", "-s", name, "-c", dir}
	var parts []string
	parts = append(parts, "env")
	// Options (-u) must precede variable assignments for BSD env on macOS.
	for _, v := range unsetEnv {
		parts = append(parts, "-u", shellQuote(v))
	}
	parts = append(parts, "PATH="+shellQuote(os.Getenv("PATH")))
	parts = append(parts, shellQuote(command))
	for _, a := range args {
		parts = append(parts, shellQuote(a))
	}
	tmuxArgs = append(tmuxArgs, strings.Join(parts, " "))

	cmd := exec.Command("tmux", tmuxArgs...)
	if out, err := cmd.CombinedOutput(); err != nil {
		return nil, fmt.Errorf("tmux new-session: %w\n%s", err, out)
	}
	// Keep the pane around after the command exits so we can capture error output.
	setCmd := exec.Command("tmux", "set-option", "-t", name, "remain-on-exit", "on")
	_ = setCmd.Run()
	return s, nil
}

func (s *TmuxSession) Send(input string) error {
	preSend := stableContent(s.Capture())
	// Send text and Enter separately — some TUIs can swallow Enter
	// if it arrives before the input handler finishes processing the text.
	if err := s.SendKeys(input); err != nil {
		return err
	}
	time.Sleep(200 * time.Millisecond)
	if err := s.SendKeys("Enter"); err != nil {
		return err
	}

	// Wait for the terminal to reflect the echoed input, then snapshot.
	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) {
		time.Sleep(200 * time.Millisecond)
		current := stableContent(s.Capture())
		if current != preSend {
			s.stableAtSend = current
			return nil
		}
	}
	s.stableAtSend = stableContent(s.Capture())
	return nil
}

// SendKeys sends raw tmux key names without appending Enter.
func (s *TmuxSession) SendKeys(keys ...string) error {
	args := append([]string{"send-keys", "-t", s.name}, keys...)
	cmd := exec.Command("tmux", args...)
	out, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("tmux send-keys: %w\n%s", err, out)
	}
	return nil
}

const (
	settleTime   = 2 * time.Second
	pollInterval = 500 * time.Millisecond
)

// stableContent returns the content with the last few lines stripped,
// so that TUI status bar updates don't prevent the settle timer.
func stableContent(content string) string {
	lines := strings.Split(content, "\n")
	if len(lines) > 3 {
		lines = lines[:len(lines)-3]
	}
	return strings.Join(lines, "\n")
}

func (s *TmuxSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
	re, err := regexp.Compile(pattern)
	if err != nil {
		return "", fmt.Errorf("invalid pattern: %w", err)
	}

	deadline := time.Now().Add(timeout)
	var matchedAt time.Time
	var lastStable string
	contentChanged := s.stableAtSend == "" // skip change requirement for initial waits

	for time.Now().Before(deadline) {
		content := s.Capture()
		stable := stableContent(content)

		// Bail early if the process has exited and the pattern doesn't match.
		if !re.MatchString(content) {
			if s.IsPaneDead() {
				return content, fmt.Errorf("process exited while waiting for %q\n--- pane content ---\n%s\n--- end pane content ---", pattern, content)
			}
			matchedAt = time.Time{}
			lastStable = ""
			time.Sleep(pollInterval)
			continue
		}

		if !contentChanged && stable != s.stableAtSend {
			contentChanged = true
		}

		if stable != lastStable {
			matchedAt = time.Now()
			lastStable = stable
			time.Sleep(pollInterval)
			continue
		}

		if contentChanged && time.Since(matchedAt) >= settleTime {
			return content, nil
		}

		time.Sleep(pollInterval)
	}
	content := s.Capture()
	return content, fmt.Errorf("timed out waiting for %q after %s\n--- pane content ---\n%s\n--- end pane content ---", pattern, timeout, content)
}

// IsPaneDead returns true if the process inside the tmux pane has exited.
func (s *TmuxSession) IsPaneDead() bool {
	cmd := exec.Command("tmux", "display-message", "-t", s.name, "-p", "#{pane_dead}")
	out, err := cmd.Output()
	if err != nil {
		return true
	}
	return strings.TrimSpace(string(out)) == "1"
}

func (s *TmuxSession) Capture() string {
	cmd := exec.Command("tmux", "capture-pane", "-t", s.name, "-p")
	out, _ := cmd.Output()
	return strings.TrimRight(string(out), "\n")
}

func (s *TmuxSession) Close() error {
	for _, fn := range s.cleanups {
		fn()
	}
	cmd := exec.Command("tmux", "kill-session", "-t", s.name)
	out, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("tmux kill-session: %w\n%s", err, out)
	}
	return nil
}

// shellQuote wraps s in single quotes with proper escaping for POSIX shells.
func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
}

package agents

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"syscall"
	"time"
)

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "kiro" {
		return
	}
	Register(&Kiro{})
	RegisterGate("kiro", 2)
}

// Kiro implements Agent for the Kiro CLI (kiro-cli-chat).
type Kiro struct{}

func (k *Kiro) Name() string               { return "kiro" }
func (k *Kiro) Binary() string             { return "kiro-cli-chat" }
func (k *Kiro) EntireAgent() string        { return "kiro" }
func (k *Kiro) PromptPattern() string      { return `>` }
func (k *Kiro) TimeoutMultiplier() float64 { return 1.0 }
func (k *Kiro) IsExternalAgent() bool      { return true }

func (k *Kiro) IsTransientError(out Output, _ error) bool {
	combined := out.Stdout + out.Stderr
	transientPatterns := []string{
		"overloaded",
		"rate limit",
		"529",
		"503",
		"500",
		"ECONNRESET",
		"ETIMEDOUT",
	}
	for _, p := range transientPatterns {
		if strings.Contains(combined, p) {
			return true
		}
	}
	return false
}

func (k *Kiro) Bootstrap() error {
	// No-op locally. On CI, write config for non-interactive auth if needed.
	return nil
}

func (k *Kiro) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	cfg := &runConfig{}
	for _, o := range opts {
		o(cfg)
	}

	bin, err := exec.LookPath(k.Binary())
	if err != nil {
		return Output{}, fmt.Errorf("%s not in PATH: %w", k.Binary(), err)
	}

	args := []string{"chat", "--no-interactive", "--trust-all-tools", "--agent", "entire", prompt}
	displayArgs := []string{"chat", "--no-interactive", "--trust-all-tools", "--agent", "entire", fmt.Sprintf("%q", prompt)}

	env := filterEnv(os.Environ(), "ENTIRE_TEST_TTY")

	cmd := exec.CommandContext(ctx, bin, args...)
	cmd.Dir = dir
	cmd.Env = env
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error {
		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
	}
	cmd.WaitDelay = 5 * time.Second

	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err = cmd.Run()
	exitCode := 0
	if err != nil {
		exitErr := &exec.ExitError{}
		if errors.As(err, &exitErr) {
			exitCode = exitErr.ExitCode()
		} else {
			exitCode = -1
		}
	}

	return Output{
		Command:  k.Binary() + " " + strings.Join(displayArgs, " "),
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
		ExitCode: exitCode,
	}, err
}

func (k *Kiro) StartSession(ctx context.Context, dir string) (Session, error) {
	name := fmt.Sprintf("kiro-test-%d", time.Now().UnixNano())

	s, err := NewTmuxSession(name, dir, []string{"ENTIRE_TEST_TTY"}, k.Binary(), "chat", "--agent", "entire")
	if err != nil {
		return nil, err
	}

	// Wait for the initial prompt to appear.
	if _, err := s.WaitFor(k.PromptPattern(), 30*time.Second); err != nil {
		_ = s.Close()
		return nil, fmt.Errorf("waiting for initial prompt: %w", err)
	}
	s.stableAtSend = ""

	return s, nil
}

package entire

import (
	"encoding/json"
	"os"
	"os/exec"
	"strings"
	"testing"
)

// BinPath returns the path to the entire binary.
// It checks E2E_ENTIRE_BIN first, then falls back to looking in PATH.
func BinPath() string {
	if p := os.Getenv("E2E_ENTIRE_BIN"); p != "" {
		return p
	}
	if p, err := exec.LookPath("entire"); err == nil {
		return p
	}
	return "entire"
}

// RewindPoint represents a single entry from `entire rewind --list`.
type RewindPoint struct {
	ID             string `json:"id"`
	Message        string `json:"message"`
	MetadataDir    string `json:"metadata_dir"`
	Date           string `json:"date"`
	IsLogsOnly     bool   `json:"is_logs_only"`
	CondensationID string `json:"condensation_id"`
	SessionID      string `json:"session_id"`
}

// Enable runs `entire enable` for the given agent with telemetry disabled.
func Enable(t *testing.T, dir, agent string) {
	t.Helper()
	run(t, dir, "enable", "--agent", agent, "--telemetry=false")
}

// Disable runs `entire disable` in the given directory.
func Disable(t *testing.T, dir string) {
	t.Helper()
	run(t, dir, "disable")
}

// RewindList runs `entire rewind --list` and parses the JSON output.
func RewindList(t *testing.T, dir string) []RewindPoint {
	t.Helper()
	out := run(t, dir, "rewind", "--list")

	var points []RewindPoint
	if err := json.Unmarshal([]byte(out), &points); err != nil {
		t.Fatalf("parse rewind list: %v\nraw output: %s", err, out)
	}
	return points
}

// Rewind runs `entire rewind --to <id>`. Returns an error instead of
// failing the test, since callers may test failure cases.
func Rewind(t *testing.T, dir, id string) error {
	t.Helper()
	return runErr(dir, "rewind", "--to", id)
}

// RewindLogsOnly runs `entire rewind --to <id> --logs-only`.
func RewindLogsOnly(t *testing.T, dir, id string) error {
	t.Helper()
	return runErr(dir, "rewind", "--to", id, "--logs-only")
}

// run executes an `entire` subcommand in dir and fails the test on error.
func run(t *testing.T, dir string, args ...string) string {
	t.Helper()
	cmd := exec.Command(BinPath(), args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")

	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("entire %s failed: %v\n%s", strings.Join(args, " "), err, out)
	}
	return strings.TrimSpace(string(out))
}

// runErr executes an `entire` subcommand in dir and returns any error.
func runErr(dir string, args ...string) error {
	cmd := exec.Command(BinPath(), args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")

	out, err := cmd.CombinedOutput()
	if err != nil {
		return &ExecError{
			Args:   args,
			Err:    err,
			Output: string(out),
		}
	}
	return nil
}

// ExecError wraps an entire CLI execution failure with its output.
type ExecError struct {
	Args   []string
	Err    error
	Output string
}

func (e *ExecError) Error() string {
	return "entire " + strings.Join(e.Args, " ") + ": " + e.Err.Error() + "\n" + e.Output
}

func (e *ExecError) Unwrap() error {
	return e.Err
}

package testutil

import "time"

// TokenUsage tracks API token consumption for a checkpoint.
type TokenUsage struct {
	InputTokens         int `json:"input_tokens"`
	CacheCreationTokens int `json:"cache_creation_tokens"`
	CacheReadTokens     int `json:"cache_read_tokens"`
	OutputTokens        int `json:"output_tokens"`
	APICallCount        int `json:"api_call_count"`
}

// Attribution tracks code authorship for a checkpoint.
type Attribution struct {
	CalculatedAt    time.Time `json:"calculated_at"`
	AgentLines      int       `json:"agent_lines"`
	HumanAdded      int       `json:"human_added"`
	HumanModified   int       `json:"human_modified"`
	HumanRemoved    int       `json:"human_removed"`
	TotalCommitted  int       `json:"total_committed"`
	AgentPercentage float64   `json:"agent_percentage"`
}

// CheckpointMetadata represents the top-level metadata.json for a checkpoint.
type CheckpointMetadata struct {
	CLIVersion       string       `json:"cli_version"`
	CheckpointID     string       `json:"checkpoint_id"`
	Strategy         string       `json:"strategy"`
	Branch           string       `json:"branch"`
	CheckpointsCount int          `json:"checkpoints_count"`
	FilesTouched     []string     `json:"files_touched"`
	Sessions         []SessionRef `json:"sessions"`
	TokenUsage       TokenUsage   `json:"token_usage"`
}

// SessionRef is a pointer to a session within checkpoint metadata.
type SessionRef struct {
	Metadata    string `json:"metadata"`
	Transcript  string `json:"transcript"`
	Context     string `json:"context"`
	ContentHash string `json:"content_hash"`
	Prompt      string `json:"prompt"`
}

// SessionMetadata represents a session's metadata.json within a checkpoint.
type SessionMetadata struct {
	CLIVersion         string      `json:"cli_version"`
	CheckpointID       string      `json:"checkpoint_id"`
	SessionID          string      `json:"session_id"`
	Strategy           string      `json:"strategy"`
	CreatedAt          time.Time   `json:"created_at"`
	Branch             string      `json:"branch"`
	Agent              string      `json:"agent"`
	CheckpointsCount   int         `json:"checkpoints_count"`
	FilesTouched       []string    `json:"files_touched"`
	TokenUsage         TokenUsage  `json:"token_usage"`
	InitialAttribution Attribution `json:"initial_attribution"`
	TranscriptPath     string      `json:"transcript_path"`
}

// CheckpointPath converts a checkpoint ID to its two-level directory path.
func CheckpointPath(id string) string {
	return id[:2] + "/" + id[2:]
}

package testutil

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"testing"
	"time"
)

// ArtifactRoot is the absolute path to the artifact output directory.
// Must be set in TestMain before any tests run.
var ArtifactRoot string

// ArtifactTimestamp is the timestamp subdirectory for this test run.
var ArtifactTimestamp = time.Now().Format("2006-01-02T15-04-05")

var runDirOverride string

// SetRunDir overrides the artifact run directory (e.g. from E2E_ARTIFACT_DIR).
func SetRunDir(dir string) {
	runDirOverride = dir
}

// ArtifactRunDir returns the directory for the current test run.
func ArtifactRunDir() string {
	if runDirOverride != "" {
		return runDirOverride
	}
	return filepath.Join(ArtifactRoot, ArtifactTimestamp)
}

func artifactDir(t *testing.T) string {
	t.Helper()
	name := strings.ReplaceAll(t.Name(), "/", "-")
	dir := filepath.Join(ArtifactRunDir(), name)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Logf("warning: failed to create artifact dir: %v", err)
	}
	return dir
}

// CaptureArtifacts captures git state, checkpoint metadata, entire logs,
// and console output to the artifact directory.
func CaptureArtifacts(t *testing.T, s *RepoState) {
	t.Helper()
	dir := s.ArtifactDir

	writeArtifact(t, dir, "git-log.txt",
		gitOutputSafe(s.Dir, "log", "--decorate", "--graph", "--all"))

	writeArtifact(t, dir, "git-tree.txt",
		gitOutputSafe(s.Dir, "ls-tree", "-r", "HEAD")+
			"\n--- entire/checkpoints/v1 ---\n"+
			gitOutputSafe(s.Dir, "ls-tree", "-r", "entire/checkpoints/v1"))

	// Capture final pane content from interactive sessions, then close.
	if s.session != nil {
		pane := s.session.Capture()
		writeArtifact(t, dir, "pane.txt", pane)
		_ = s.session.Close()
	}

	if t.Failed() {
		writeArtifact(t, dir, "FAIL", "")
	} else {
		writeArtifact(t, dir, "PASS", "")
	}

	captureCheckpointMetadata(t, s, dir)
	captureEntireLogs(t, s.Dir, dir)

	if os.Getenv("E2E_KEEP_REPOS") != "" {
		link := filepath.Join(dir, "repo")
		if err := os.Symlink(s.Dir, link); err != nil {
			t.Logf("warning: failed to symlink repo: %v", err)
		}
	}
}

func captureCheckpointMetadata(t *testing.T, s *RepoState, outDir string) {
	t.Helper()
	commits := NewCheckpointCommits(t, s)
	metaDir := filepath.Join(outDir, "checkpoint-metadata")

	cpIDRe := regexp.MustCompile(`(?m)^Checkpoint:\s+(\S+)`)
	for _, sha := range commits {
		msg := gitOutputSafe(s.Dir, "log", "-1", "--format=%B", sha)
		m := cpIDRe.FindStringSubmatch(msg)
		if m == nil || len(m[1]) < 3 {
			continue
		}
		id := m[1]
		cpPath := CheckpointPath(id)

		cpDir := filepath.Join(metaDir, cpPath)
		_ = os.MkdirAll(cpDir, 0o755)
		raw := gitOutputSafe(s.Dir, "show", sha+":"+cpPath+"/metadata.json")
		writeArtifact(t, cpDir, "metadata.json", raw)

		for i := 0; ; i++ {
			sessPath := fmt.Sprintf("%s/%d/metadata.json", cpPath, i)
			raw := gitOutputSafe(s.Dir, "show", sha+":"+sessPath)
			if raw == "" {
				break
			}
			sessDir := filepath.Join(cpDir, strconv.Itoa(i))
			_ = os.MkdirAll(sessDir, 0o755)
			writeArtifact(t, sessDir, "metadata.json", raw)
		}
	}
}

func captureEntireLogs(t *testing.T, repoDir, outDir string) {
	t.Helper()
	logDir := filepath.Join(repoDir, ".entire", "logs")
	entries, err := os.ReadDir(logDir)
	if err != nil {
		return
	}
	dst := filepath.Join(outDir, "entire-logs")
	_ = os.MkdirAll(dst, 0o755)
	for _, e := range entries {
		data, err := os.ReadFile(filepath.Join(logDir, e.Name()))
		if err != nil {
			continue
		}
		writeArtifact(t, dst, e.Name(), string(data))
	}
}

func writeArtifact(t *testing.T, dir, name, content string) {
	t.Helper()
	path := filepath.Join(dir, name)
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Logf("warning: failed to write artifact %s: %v", path, err)
	}
}

func gitOutputSafe(dir string, args ...string) string {
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	out, err := cmd.Output()
	if err != nil {
		return ""
	}
	return string(out)
}

package testutil

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/entireio/external-agents/e2e/agents"
